<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import type {Trip} from '@/types'
import {allRecords,folderSummaries} from '@/services/planner.service'
import api from '@/services/api.service'
import AppSheet from '@/components/shared/AppSheet.vue'
import SignInAgain from '@/components/shared/SignInAgain.vue'
import {isSignInRequired} from '@/services/request-errors'
import '@/styles/field-notes.css'
const trips=ref<Trip[]>([]),loading=ref(true),error=ref(''),search=ref(''),failed=ref<Record<string,boolean>>({})
const summaries=ref<Awaited<ReturnType<typeof folderSummaries>>>([]),menu=ref<Trip|null>(null),name=ref(''),busy=ref(false),sheetError=ref(''),deleting=ref(false)
const visible=computed(()=>trips.value.filter(t=>(t.title+' '+(t.destination||'')).toLowerCase().includes(search.value.toLowerCase())))
const needsSignIn=ref(false)
async function load(){
 if(loading.value&&loadedOnce)return
 loadedOnce=true;loading.value=true;error.value='';needsSignIn.value=false
 try{const records=await allRecords<Trip>('trips');const counts=records.length?await folderSummaries():[];trips.value=records;summaries.value=counts}
 catch(e){needsSignIn.value=isSignInRequired(e);error.value='We couldn’t open your trips. Please try again.'}
 finally{loading.value=false}
}
let loadedOnce=false
onMounted(load)
function summary(t:Trip){return summaries.value.find(s=>s.trip_id===t.id)}
function dates(t:Trip){const first=summary(t)?.first_date||t.start_date,last=summary(t)?.last_date||t.end_date;if(!first)return 'Dates to come';const fmt=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'});return fmt(first)+(last&&last!==first?' – '+fmt(last):'')}
function options(t:Trip){menu.value=t;name.value=t.title;sheetError.value='';deleting.value=false}
async function rename(){if(!menu.value||!name.value.trim()||busy.value)return;busy.value=true;sheetError.value='';try{await api.put('/trips/'+menu.value.id,{title:name.value.trim()});menu.value.title=name.value.trim();menu.value=null}catch{sheetError.value='We couldn’t save your trip. Your details are still here.'}finally{busy.value=false}}
async function remove(){if(!menu.value||busy.value)return;busy.value=true;sheetError.value='';try{await api.delete('/trips/'+menu.value.id);trips.value=trips.value.filter(t=>t.id!==menu.value!.id);menu.value=null}catch{sheetError.value='We couldn’t delete this trip. Please retry.'}finally{busy.value=false}}
</script>
<template><main class="field-notes trip-collection"><header class="collection-heading"><div><p class="eyebrow">Your personal travel collection</p><h1>Trips<span>.</span></h1><p>Small escapes. Grand adventures. A folder for each.</p></div><RouterLink to="/trips/new" class="button primary">＋ New trip</RouterLink></header><label v-if="!loading&&!error&&trips.length" class="trip-search"><span class="sr-only">Search trips</span><input v-model="search" type="search" placeholder="Find a trip…" /></label><p v-if="loading" role="status" class="loading">Opening your collection…</p><SignInAgain v-else-if="needsSignIn" @restored="load" /><p v-else-if="error" role="alert" class="notice">{{error}} <button @click="load">Retry</button></p><div v-else-if="visible.length" class="trip-grid"><article v-for="trip in visible" :key="trip.id" class="trip-folder"><div class="folder-tab" aria-hidden="true">CRONEVIA · TRAVEL</div><button class="folder-menu" :aria-label="'Options for '+trip.title" @click="options(trip)">•••</button><RouterLink :to="'/trips/'+trip.id" class="folder-link"><div v-if="trip.cover_image_path&&!failed[trip.id]" class="trip-cover"><img :src="trip.cover_image_path" alt="" loading="lazy" @error="failed[trip.id]=true" /></div><div class="folder-body"><p class="eyebrow">{{summary(trip)?.place_count||0}} {{summary(trip)?.place_count===1?'place':'places'}} <span v-if="trip.status==='archived'">· Archived</span></p><h2>{{trip.title}}</h2><p class="muted">{{dates(trip)}}</p><div class="folder-footer"><span>Open itinerary</span><span aria-hidden="true">↗</span></div></div></RouterLink></article></div><section v-else-if="!trips.length" class="empty first-trip"><svg class="empty-folder" viewBox="0 0 120 86" fill="none" aria-hidden="true"><path d="M10 25V15a6 6 0 0 1 6-6h29l12 12h47a6 6 0 0 1 6 6v46a6 6 0 0 1-6 6H16a6 6 0 0 1-6-6Z" fill="#e9dfc9" stroke="#b9ab90"/><path d="M10 31h100v42a6 6 0 0 1-6 6H16a6 6 0 0 1-6-6Z" fill="#fff9ed" stroke="#b9ab90"/><path d="M50 55h20m-10-10v20" stroke="#89977a" stroke-width="2" stroke-linecap="round"/></svg><h2>Your first journey starts here.</h2><p>Create a trip, then add places and times as you go.</p><RouterLink to="/trips/new" class="button primary">Create your first trip</RouterLink></section><section v-else class="empty"><h2>No matching trips</h2><p>Try another name or clear your search.</p><button @click="search=''">Clear search</button></section>
 <AppSheet :model-value="!!menu" title="Your trip folder" @update:model-value="!busy&&(menu=null)"><form v-if="menu" class="form-grid" @submit.prevent="rename"><label>Trip name<input v-model="name" required maxlength="255" :disabled="busy" /></label><p v-if="sheetError" role="alert" class="notice">{{sheetError}}</p><button class="primary" :disabled="busy||!name.trim()">{{busy?'Saving…':sheetError&&!deleting?'Retry':'Save name'}}</button><RouterLink :to="{path:'/trips/'+menu.id,query:{cover:'1'}}" class="button">Change cover</RouterLink><button v-if="!deleting" type="button" @click="deleting=true" :disabled="busy">Delete trip</button><template v-else><p class="muted">Delete this trip folder? It will disappear from your collection. Linked memories and journals are kept.</p><button type="button" :disabled="busy" @click="remove">Confirm deletion</button></template></form></AppSheet>
</main></template>
<style scoped>.collection-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:10px 0 26px}.collection-heading h1{font-size:48px;margin:5px 0}.collection-heading h1 span{color:#879278}.collection-heading p:not(.eyebrow){font-size:15px;color:#80745f;line-height:1.6}.collection-heading .primary{flex-shrink:0}.trip-search{max-width:560px;margin-bottom:38px}.trip-search input{font-size:16px}.trip-grid{display:grid;gap:44px 24px;padding-top:14px}.trip-folder{position:relative;background:#fff9ed;border:1px solid #d9cdb8;border-radius:0 12px 12px 12px;box-shadow:0 5px 16px #59402708;min-width:0}.folder-tab{position:absolute;left:-1px;top:-23px;height:24px;background:#e9dfc9;border:1px solid #d9cdb8;border-bottom:0;border-radius:9px 14px 0 0;padding:7px 22px 0 14px;font-size:8px;letter-spacing:.13em;color:#817459}.folder-link{display:flex;flex-direction:column;height:100%;overflow:hidden;border-radius:0 12px 12px 12px}.folder-menu{position:absolute;right:8px;top:8px;min-width:44px;min-height:44px;z-index:1;background:#fffaf0e8;border:0;letter-spacing:2px}.folder-body{padding:28px 22px 20px;display:flex;flex-direction:column;flex:1}.folder-body>.eyebrow{padding-right:35px;font-size:10px;color:#7b876b}.folder-body h2{font-size:29px;margin:14px 0 12px;overflow-wrap:anywhere}.folder-body .muted{font-size:13px;line-height:1.6}.folder-footer{display:flex;justify-content:space-between;padding-top:16px;border-top:1px dashed #cfc4af;color:#74283c;font-size:13px;margin-top:auto}.folder-body .muted{margin-bottom:24px}.trip-cover{height:150px;background:#e0e3d6}.trip-cover img{width:100%;height:100%;object-fit:cover}.empty h2{font-size:32px}.empty .button{margin-top:20px}@media(min-width:680px){.trip-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(min-width:1100px){.trip-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.collection-heading{align-items:flex-start;flex-direction:column;gap:16px}.collection-heading h1{font-size:38px}.collection-heading .primary{width:100%}.trip-collection{padding:20px 16px}.trip-search{margin-bottom:34px}}
</style>

<style scoped>.first-trip{max-width:720px;margin:30px auto}.empty-folder{width:112px;height:80px;margin:0 auto 18px}.first-trip h2{font-size:clamp(26px,4vw,32px)}</style>
